const ASSETS = {"/index.html":{"contentType":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <meta\n      name=\"description\"\n      content=\"Athlete 365 is a local-first calisthenics training app with a 365-day plan, XP, levels, adaptive workouts, and progress tracking.\"\n    />\n    <title>Athlete 365</title>\n    <link rel=\"manifest\" href=\"./manifest.webmanifest\" />\n    <link rel=\"stylesheet\" href=\"./src/styles.css\" />\n  </head>\n  <body>\n    <div id=\"app\"></div>\n    <script type=\"module\" src=\"./src/app.js\"></script>\n  </body>\n</html>\n"},"/manifest.webmanifest":{"contentType":"application/manifest+json; charset=utf-8","body":"{\n  \"name\": \"Athlete 365\",\n  \"short_name\": \"Athlete365\",\n  \"start_url\": \".\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#0f172a\",\n  \"theme_color\": \"#14b8a6\",\n  \"icons\": []\n}\n"},"/sw.js":{"contentType":"text/javascript; charset=utf-8","body":"const CACHE = \"athlete-365-v3\";\nconst ASSETS = [\n  \"./\",\n  \"./index.html\",\n  \"./manifest.webmanifest\",\n  \"./src/app.js\",\n  \"./src/program.js\",\n  \"./src/state.js\",\n  \"./src/styles.css\"\n];\n\nself.addEventListener(\"install\", (event) => {\n  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(ASSETS)));\n});\n\nself.addEventListener(\"fetch\", (event) => {\n  event.respondWith(\n    caches.match(event.request).then((cached) => cached || fetch(event.request))\n  );\n});\n\nself.addEventListener(\"activate\", (event) => {\n  event.waitUntil(\n    caches.keys().then((keys) => Promise.all(keys.filter((key) => key !== CACHE).map((key) => caches.delete(key))))\n  );\n});\n"},"/src/app.js":{"contentType":"text/javascript; charset=utf-8","body":"import { exerciseLibrary, levelFromXp, xpForLevel, validateProgram } from \"./program.js\";\nimport {\n  completeMicroTask,\n  completeTask,\n  completeWorkout,\n  dailyTasksFor,\n  exportCsv,\n  exportJson,\n  isSignedIn,\n  loadState,\n  programForState,\n  readinessAdvice,\n  resetState,\n  saveState,\n  signIn,\n  signOut,\n  stats,\n  substituteExercise,\n  taskKey,\n  taskProgress,\n  toggleSet\n} from \"./state.js\";\n\nlet state = loadState();\nlet program = programForState(state);\nlet route = \"tasks\";\nlet selectedDay = currentProgramDay();\n\nconst app = document.querySelector(\"#app\");\n\nif (\"serviceWorker\" in navigator) {\n  navigator.serviceWorker.register(\"./sw.js\").catch(() => {});\n}\n\nrender();\n\nfunction render() {\n  document.documentElement.dataset.theme = state.profile.theme;\n  program = programForState(state);\n  const errors = validateProgram(program);\n  app.innerHTML = `\n    <header class=\"shell-header\">\n      <section>\n        <p class=\"eyebrow\">Athlete 365</p>\n        <h1>Daily fitness task RPG</h1>\n      </section>\n      <nav aria-label=\"Primary navigation\">\n        ${navButton(\"tasks\", \"Tasks\")}\n        ${navButton(\"dashboard\", \"Workout\")}\n        ${navButton(\"calendar\", \"Calendar\")}\n        ${navButton(\"program\", \"Program\")}\n        ${navButton(\"progress\", \"Progress\")}\n        ${navButton(\"library\", \"Library\")}\n        ${navButton(\"settings\", \"Settings\")}\n      </nav>\n    </header>\n    <main class=\"app-shell\">\n      ${errors.length ? `<aside class=\"warning\">${errors.join(\" \")}</aside>` : \"\"}\n      ${view()}\n    </main>\n  `;\n  bindEvents();\n}\n\nfunction view() {\n  if (!isSignedIn(state)) return loginView();\n  if (route === \"tasks\") return tasksView();\n  if (route === \"calendar\") return calendarView();\n  if (route === \"program\") return programView();\n  if (route === \"progress\") return progressView();\n  if (route === \"library\") return libraryView();\n  if (route === \"settings\") return settingsView();\n  return dashboardView();\n}\n\nfunction loginView() {\n  return `\n    <section class=\"login-shell\">\n      <form class=\"login-card\" id=\"login-form\">\n        <p class=\"eyebrow\">Athlete 365</p>\n        <h2>Enter your athlete name</h2>\n        <p>This app uses a simple local profile. No ChatGPT sign-in is needed for the app itself.</p>\n        <label class=\"field\">\n          Username\n          <input name=\"username\" value=\"Anton\" autocomplete=\"name\" required minlength=\"2\" />\n        </label>\n        <button class=\"primary\" type=\"submit\">Start training</button>\n      </form>\n    </section>\n  `;\n}\n\nfunction tasksView() {\n  const day = withSubstitutions(program[selectedDay - 1]);\n  const tasks = dailyTasksFor(day);\n  const progress = taskProgress(state, day);\n  const s = stats(state, program);\n  const remainingXp = tasks\n    .filter((task) => !state.taskCompletions[taskKey(day.dayNumber, task.id)])\n    .reduce((sum, task) => sum + task.xp, 0);\n  return `\n    <section class=\"hero-grid\">\n      <article class=\"today-panel\">\n        <div class=\"panel-head\">\n          <div>\n            <p class=\"eyebrow\">Quick task queue</p>\n            <h2>${state.profile.name}'s quick tasks</h2>\n            <p>Most tasks need no equipment. Higher tiers unlock as your total level rises.</p>\n          </div>\n          <strong class=\"level-badge\">${s.microTasksDone} done</strong>\n        </div>\n        <div class=\"micro-task-list\">\n          ${state.microTasks.map((task, index) => microTaskCard(task, index)).join(\"\")}\n        </div>\n        <div class=\"planned-head\">\n          <div>\n            <p class=\"eyebrow\">Day ${day.dayNumber} planned workout</p>\n            <h2>Workout tasks and big XP reward</h2>\n            <p>${day.title} - ${day.phase} - ${day.duration} minutes</p>\n          </div>\n          <strong class=\"level-badge\">${progress.completed}/${progress.total}</strong>\n        </div>\n        <div class=\"task-summary\">\n          <div>\n            <span>Planned workout task progress</span>\n            <div class=\"bar\"><span style=\"width:${progress.percent}%\"></span></div>\n          </div>\n          <strong>${remainingXp} XP left today</strong>\n        </div>\n        <div class=\"task-list\">\n          ${tasks.map((task) => taskCard(task, day)).join(\"\")}\n        </div>\n      </article>\n      <aside class=\"side-panel\">\n        ${metricCards(s)}\n        ${skillsPanel()}\n        <article class=\"card\">\n          <h3>Task tiers</h3>\n          <p>Tier 1 is simple bodyweight work like 10 push-ups, 10 sit-ups, squats, planks, lunges, and mobility. Later tiers add rounds, density blocks, and optional home equipment.</p>\n        </article>\n        <article class=\"card\">\n          <h3>Streak bonuses</h3>\n          <p>Clear all planned workout tasks to extend the task streak. Bonuses are paid once when you hit each milestone.</p>\n          <div class=\"bonus-grid\">\n            ${bonusPill(\"3 days\", \"75 XP\", state.streakBonuses[\"tasks-3\"])}\n            ${bonusPill(\"1 week\", \"200 XP\", state.streakBonuses[\"tasks-7\"])}\n            ${bonusPill(\"14 days\", \"450 XP\", state.streakBonuses[\"tasks-14\"])}\n            ${bonusPill(\"30 days\", \"1200 XP\", state.streakBonuses[\"tasks-30\"])}\n          </div>\n        </article>\n        <article class=\"card\">\n          <h3>Big reward task</h3>\n          <p>The full workout remains the largest planned task. The quick queue is for small wins throughout the day.</p>\n          <button data-route=\"dashboard\">Open workout detail</button>\n        </article>\n      </aside>\n    </section>\n  `;\n}\n\nfunction microTaskCard(task, index) {\n  return `\n    <article class=\"task-card micro tier-${task.tier}\">\n      <button type=\"button\" class=\"task-check\" data-micro-task=\"${index}\" aria-label=\"Complete ${task.title}\">+</button>\n      <div>\n        <p class=\"eyebrow\">Tier ${task.tier} - ${task.skills.join(\" + \")}</p>\n        <h3>${task.title}</h3>\n        <p>${task.detail}</p>\n        <small>${task.equipment.length ? `Needs ${task.equipment.join(\", \")}` : \"No equipment\"}</small>\n      </div>\n      <strong>${task.xp} XP</strong>\n    </article>\n  `;\n}\n\nfunction taskCard(task, day) {\n  const done = state.taskCompletions[taskKey(day.dayNumber, task.id)];\n  return `\n    <article class=\"task-card ${task.featured ? \"featured\" : \"\"} ${done ? \"done\" : \"\"}\">\n      <button type=\"button\" class=\"task-check\" data-task=\"${task.id}\" ${done ? \"disabled\" : \"\"} aria-label=\"Complete ${task.title}\">\n        ${done ? \"✓\" : \"+\"}\n      </button>\n      <div>\n        <p class=\"eyebrow\">${task.featured ? \"Big reward task\" : task.skills.join(\" + \")}</p>\n        <h3>${task.title}</h3>\n        <p>${task.detail}</p>\n      </div>\n      <strong>${task.xp} XP</strong>\n    </article>\n  `;\n}\n\nfunction dashboardView() {\n  const day = program[selectedDay - 1];\n  const workout = withSubstitutions(day);\n  const s = stats(state, program);\n  return `\n    <section class=\"hero-grid\">\n      <article class=\"today-panel\">\n        <div class=\"panel-head\">\n          <div>\n            <p class=\"eyebrow\">Day ${day.dayNumber} / Block ${day.block} / Week ${day.weekInBlock}</p>\n            <h2>${day.title}</h2>\n            <p>${day.phase} - ${day.focus}</p>\n          </div>\n          <strong class=\"level-badge\">${state.workouts[String(day.dayNumber)]?.completed ? \"Complete\" : `${day.duration} min`}</strong>\n        </div>\n        ${readinessCard()}\n        <form id=\"workout-form\">\n          ${sectionList(\"Warm-up\", day.warmup)}\n          <div class=\"exercise-stack\">\n            ${workout.exercises.map((exercise, index) => exerciseCard(exercise, day, index)).join(\"\")}\n            ${workout.finisher ? exerciseCard(workout.finisher, day, workout.exercises.length, true) : \"\"}\n          </div>\n          ${sectionList(\"Cooldown\", day.cooldown)}\n          <label class=\"field wide\">\n            Workout notes\n            <textarea name=\"notes\" rows=\"3\" placeholder=\"Energy, form, substitutions, personal records...\">${state.workouts[String(day.dayNumber)]?.notes || \"\"}</textarea>\n          </label>\n          <div class=\"actions\">\n            <button class=\"primary\" type=\"submit\">${state.workouts[String(day.dayNumber)]?.completed ? \"Workout logged\" : \"Finish workout and earn XP\"}</button>\n            <button type=\"button\" data-route=\"tasks\">Back to tasks</button>\n            <button type=\"button\" data-route=\"calendar\">Pick another day</button>\n          </div>\n        </form>\n      </article>\n      <aside class=\"side-panel\">\n        ${metricCards(s)}\n        ${skillsPanel()}\n        <article class=\"card\">\n          <h3>Coaching notes</h3>\n          <p>${day.notes}</p>\n          <p>${day.recovery}</p>\n        </article>\n        <article class=\"card\">\n          <h3>Achievements</h3>\n          <div class=\"chips\">${(state.achievements.length ? state.achievements : [\"Start today to unlock achievements\"]).map((a) => `<span>${a}</span>`).join(\"\")}</div>\n        </article>\n      </aside>\n    </section>\n  `;\n}\n\nfunction readinessCard() {\n  const saved = state.workouts[String(selectedDay)] || {};\n  const readiness = {\n    energy: saved.energy || 3,\n    sleep: saved.sleep || 3,\n    soreness: saved.soreness || 2,\n    jointPain: saved.jointPain || 0\n  };\n  return `\n    <article class=\"readiness\">\n      <div>\n        <h3>Readiness</h3>\n        <p id=\"readiness-advice\">${readinessAdvice(program[selectedDay - 1], readiness)}</p>\n      </div>\n      ${rangeField(\"energy\", \"Energy\", readiness.energy, 1, 5)}\n      ${rangeField(\"sleep\", \"Sleep\", readiness.sleep, 1, 5)}\n      ${rangeField(\"soreness\", \"Soreness\", readiness.soreness, 1, 5)}\n      ${rangeField(\"jointPain\", \"Joint pain\", readiness.jointPain, 0, 10)}\n      <label class=\"field mini\">Bodyweight<input name=\"bodyweight\" value=\"${saved.bodyweight || \"\"}\" placeholder=\"optional\" /></label>\n    </article>\n  `;\n}\n\nfunction exerciseCard(exercise, day, index, finisher = false) {\n  return `\n    <article class=\"exercise-card ${exercise.substituted ? \"subbed\" : \"\"}\">\n      <div class=\"exercise-head\">\n        <div>\n          <p class=\"eyebrow\">${finisher ? \"Optional finisher\" : exercise.category}</p>\n          <h3>${exercise.name}</h3>\n          ${exercise.substituted ? `<p class=\"sub-note\">Substituted for ${exercise.originalName}; missing ${exercise.missing.join(\", \")}.</p>` : \"\"}\n        </div>\n        <strong>${exercise.sets} x ${exercise.reps}</strong>\n      </div>\n      <dl>\n        <div><dt>Rest</dt><dd>${exercise.restSeconds}s</dd></div>\n        <div><dt>Tempo</dt><dd>${exercise.tempo}</dd></div>\n        <div><dt>RIR</dt><dd>${exercise.targetRIR ?? \"easy\"}</dd></div>\n      </dl>\n      <p>${exercise.cue}</p>\n      <div class=\"set-row\">\n        ${Array.from({ length: exercise.sets }, (_, setIndex) => {\n          const key = `${day.dayNumber}:${index}:${setIndex}`;\n          return `<button type=\"button\" class=\"set ${state.completedSets[key] ? \"done\" : \"\"}\" data-set=\"${key}\" aria-label=\"Toggle set ${setIndex + 1}\">${setIndex + 1}</button>`;\n        }).join(\"\")}\n      </div>\n      <div class=\"adjust-grid\">\n        ${rangeField(`difficulty-${index}`, \"Difficulty\", 3, 1, 5)}\n        ${rangeField(`pain-${index}`, \"Pain\", 0, 0, 10)}\n        <label class=\"field mini\">Form<select name=\"form-${index}\"><option value=\"good\">Good</option><option value=\"off\">Broke down</option></select></label>\n      </div>\n      <details>\n        <summary>Regression, progression, alternatives</summary>\n        <p><b>Easier:</b> ${exercise.regression}</p>\n        <p><b>Harder:</b> ${exercise.progression}</p>\n        <p><b>Alternatives:</b> ${exercise.alternatives.join(\", \")}</p>\n      </details>\n    </article>\n  `;\n}\n\nfunction calendarView() {\n  return `\n    <section class=\"page-grid\">\n      <article class=\"card span\">\n        <div class=\"panel-head\">\n          <div>\n            <p class=\"eyebrow\">365-day calendar</p>\n            <h2>Pick any training day</h2>\n          </div>\n          <input id=\"calendar-filter\" placeholder=\"Filter by phase, workout, block...\" />\n        </div>\n        <div class=\"calendar-list\">\n          ${program.map((day) => `\n            <button class=\"calendar-day ${state.workouts[String(day.dayNumber)]?.completed ? \"complete\" : \"\"} ${day.dayNumber === selectedDay ? \"current\" : \"\"}\" data-day=\"${day.dayNumber}\">\n              <span>Day ${day.dayNumber}</span>\n              <strong>${day.title}</strong>\n              <small>${day.date} - Block ${day.block} - ${day.type}</small>\n            </button>\n          `).join(\"\")}\n        </div>\n      </article>\n    </section>\n  `;\n}\n\nfunction programView() {\n  const blocks = Array.from({ length: 13 }, (_, i) => i + 1);\n  return `\n    <section class=\"page-grid\">\n      ${blocks.map((block) => {\n        const days = program.filter((day) => day.block === block);\n        const complete = days.filter((day) => state.workouts[String(day.dayNumber)]?.completed).length;\n        return `\n          <article class=\"card\">\n            <p class=\"eyebrow\">Block ${block}</p>\n            <h3>${days[0].phase}</h3>\n            <p>${block === 13 ? \"Final 29-day integration block with benchmarks and personalized choices.\" : \"Three build weeks followed by a lower-volume deload week.\"}</p>\n            <div class=\"bar\"><span style=\"width:${Math.round((complete / days.length) * 100)}%\"></span></div>\n            <small>${complete}/${days.length} workouts complete</small>\n          </article>\n        `;\n      }).join(\"\")}\n    </section>\n  `;\n}\n\nfunction progressView() {\n  const s = stats(state, program);\n  const recent = Object.entries(state.workouts).slice(-8).reverse();\n  const quick = (state.microTaskHistory || []).slice(0, 8);\n  return `\n    <section class=\"page-grid\">\n      <article class=\"card span\">${metricCards(s)}</article>\n      <article class=\"card span\">${skillsPanel()}</article>\n      <article class=\"card\">\n        <h3>Recent quick tasks</h3>\n        <div class=\"timeline\">\n          ${quick.length ? quick.map((task) => `<p><b>${task.title}</b> - Tier ${task.tier} - ${task.xp} XP</p>`).join(\"\") : \"<p>No quick tasks completed yet.</p>\"}\n        </div>\n      </article>\n      <article class=\"card\">\n        <h3>Recent workouts</h3>\n        <div class=\"timeline\">\n          ${recent.length ? recent.map(([day, workout]) => `<p><b>Day ${day}</b> - ${workout.gained} XP - energy ${workout.energy}/5</p>`).join(\"\") : \"<p>No workouts logged yet.</p>\"}\n        </div>\n      </article>\n      <article class=\"card\">\n        <h3>Export</h3>\n        <p>Export all local training data as JSON or workout history as CSV.</p>\n        <div class=\"actions\"><button data-export=\"json\">JSON</button><button data-export=\"csv\">CSV</button></div>\n      </article>\n    </section>\n  `;\n}\n\nfunction libraryView() {\n  return `\n    <section class=\"page-grid\">\n      ${Object.values(exerciseLibrary).map((exercise) => `\n        <article class=\"card\">\n          <p class=\"eyebrow\">${exercise.category}</p>\n          <h3>${exercise.name}</h3>\n          <p>${exercise.description}</p>\n          <p><b>Cue:</b> ${exercise.cue}</p>\n          <p><b>Common mistake:</b> ${exercise.mistakes}</p>\n          <p><b>Regression:</b> ${exercise.regression}</p>\n          <p><b>Progression:</b> ${exercise.progression}</p>\n          <div class=\"chips\">${(exercise.equipment.length ? exercise.equipment : [\"bodyweight\"]).map((e) => `<span>${e}</span>`).join(\"\")}</div>\n        </article>\n      `).join(\"\")}\n    </section>\n  `;\n}\n\nfunction settingsView() {\n  const equipment = [\"pull-up bar\", \"rings\", \"resistance bands\", \"jump rope\", \"chair\", \"stairs\"];\n  return `\n    <section class=\"page-grid\">\n      <form class=\"card span\" id=\"settings-form\">\n        <p class=\"eyebrow\">Local settings</p>\n        <h2>Program setup</h2>\n        <div class=\"settings-grid\">\n          <label class=\"field\">Name<input name=\"name\" value=\"${state.profile.name}\" /></label>\n          <label class=\"field\">Program start date<input type=\"date\" name=\"startDate\" value=\"${state.profile.startDate}\" /></label>\n          <label class=\"field\">Training level<select name=\"level\"><option ${state.profile.level === \"Foundation\" ? \"selected\" : \"\"}>Foundation</option><option ${state.profile.level === \"Intermediate\" ? \"selected\" : \"\"}>Intermediate</option><option ${state.profile.level === \"Advanced\" ? \"selected\" : \"\"}>Advanced</option></select></label>\n          <label class=\"field\">Session duration<input type=\"number\" name=\"sessionDuration\" value=\"${state.profile.sessionDuration}\" /></label>\n          <label class=\"field\">Theme<select name=\"theme\"><option ${state.profile.theme === \"dark\" ? \"selected\" : \"\"}>dark</option><option ${state.profile.theme === \"light\" ? \"selected\" : \"\"}>light</option></select></label>\n        </div>\n        <h3>Home equipment</h3>\n        <div class=\"check-grid\">\n          ${equipment.map((item) => `<label><input type=\"checkbox\" name=\"equipment\" value=\"${item}\" ${state.profile.equipment.includes(item) ? \"checked\" : \"\"} /> ${item}</label>`).join(\"\")}\n        </div>\n        <label class=\"field wide\">Limitations<textarea name=\"limitations\" rows=\"3\">${state.profile.limitations || \"\"}</textarea></label>\n        <div class=\"actions\"><button class=\"primary\" type=\"submit\">Save settings</button><button type=\"button\" data-reset>Reset local data</button></div>\n        <div class=\"actions secondary-actions\"><button type=\"button\" data-sign-out>Sign out username</button></div>\n      </form>\n      <article class=\"card span\">\n        <h3>Safety</h3>\n        <p>This application provides general fitness programming, not medical advice. Stop exercises that cause sharp or worsening pain. Persistent pain or injury concerns should be assessed by a qualified healthcare professional. Adjust difficulty to current capacity.</p>\n      </article>\n    </section>\n  `;\n}\n\nfunction skillsPanel() {\n  return `\n    <article class=\"card\">\n      <h3>Skill levels</h3>\n      <div class=\"skill-list\">\n        ${Object.entries(state.xp).map(([skill, xp]) => {\n          const level = levelFromXp(xp);\n          const current = xpForLevel(level);\n          const next = xpForLevel(level + 1);\n          const pct = Math.round(((xp - current) / Math.max(1, next - current)) * 100);\n          return `<div><span><b>${cap(skill)}</b><small>Level ${level} - ${xp} XP</small></span><div class=\"bar\"><span style=\"width:${Math.max(0, Math.min(100, pct))}%\"></span></div></div>`;\n        }).join(\"\")}\n      </div>\n    </article>\n  `;\n}\n\nfunction metricCards(s) {\n  return `\n    <div class=\"metrics\">\n      ${metric(\"Total level\", s.totalLevel)}\n      ${metric(\"Quick tasks\", s.microTasksDone)}\n      ${metric(\"Task streak\", `${s.taskStreak} days`)}\n      ${metric(\"Workouts\", s.completedCount)}\n    </div>\n  `;\n}\n\nfunction bindEvents() {\n  app.querySelector(\"#login-form\")?.addEventListener(\"submit\", (event) => {\n    event.preventDefault();\n    const form = new FormData(event.currentTarget);\n    state = signIn(state, form.get(\"username\"));\n    saveState(state);\n    render();\n  });\n  app.querySelectorAll(\"[data-route]\").forEach((button) => button.addEventListener(\"click\", () => {\n    route = button.dataset.route;\n    render();\n  }));\n  app.querySelectorAll(\"[data-set]\").forEach((button) => button.addEventListener(\"click\", () => {\n    const [dayNumber, exerciseIndex, setIndex] = button.dataset.set.split(\":\").map(Number);\n    state = toggleSet(state, dayNumber, exerciseIndex, setIndex);\n    saveState(state);\n    render();\n  }));\n  app.querySelectorAll(\"[data-micro-task]\").forEach((button) => button.addEventListener(\"click\", () => {\n    state = completeMicroTask(state, Number(button.dataset.microTask));\n    saveState(state);\n    render();\n  }));\n  app.querySelectorAll(\"[data-task]\").forEach((button) => button.addEventListener(\"click\", () => {\n    state = completeTask(state, withSubstitutions(program[selectedDay - 1]), button.dataset.task);\n    saveState(state);\n    render();\n  }));\n  app.querySelector(\"#workout-form\")?.addEventListener(\"submit\", (event) => {\n    event.preventDefault();\n    state = completeWorkout(state, withSubstitutions(program[selectedDay - 1]), new FormData(event.currentTarget));\n    saveState(state);\n    render();\n  });\n  app.querySelectorAll(\".calendar-day\").forEach((button) => button.addEventListener(\"click\", () => {\n    selectedDay = Number(button.dataset.day);\n    route = \"tasks\";\n    render();\n  }));\n  app.querySelector(\"#calendar-filter\")?.addEventListener(\"input\", (event) => {\n    const query = event.target.value.toLowerCase();\n    app.querySelectorAll(\".calendar-day\").forEach((button) => {\n      button.hidden = !button.textContent.toLowerCase().includes(query);\n    });\n  });\n  app.querySelector(\"#settings-form\")?.addEventListener(\"submit\", (event) => {\n    event.preventDefault();\n    const form = new FormData(event.currentTarget);\n    state.profile = {\n      ...state.profile,\n      name: form.get(\"name\"),\n      startDate: form.get(\"startDate\"),\n      level: form.get(\"level\"),\n      sessionDuration: Number(form.get(\"sessionDuration\")),\n      theme: form.get(\"theme\"),\n      limitations: form.get(\"limitations\"),\n      equipment: form.getAll(\"equipment\")\n    };\n    selectedDay = currentProgramDay();\n    saveState(state);\n    render();\n  });\n  app.querySelector(\"[data-reset]\")?.addEventListener(\"click\", () => {\n    if (confirm(\"Reset all local Athlete 365 data?\")) {\n      resetState();\n      state = loadState();\n      selectedDay = currentProgramDay();\n      route = \"tasks\";\n      render();\n    }\n  });\n  app.querySelector(\"[data-sign-out]\")?.addEventListener(\"click\", () => {\n    state = signOut(state);\n    saveState(state);\n    route = \"tasks\";\n    render();\n  });\n  app.querySelectorAll(\"[data-export]\").forEach((button) => button.addEventListener(\"click\", () => {\n    const type = button.dataset.export;\n    download(type === \"json\" ? exportJson(state) : exportCsv(state), `athlete-365.${type}`, type === \"json\" ? \"application/json\" : \"text/csv\");\n  }));\n  app.querySelectorAll(\".readiness input\").forEach((input) => input.addEventListener(\"input\", () => {\n    const form = input.closest(\"form\");\n    const values = Object.fromEntries(new FormData(form));\n    app.querySelector(\"#readiness-advice\").textContent = readinessAdvice(program[selectedDay - 1], values);\n  }));\n}\n\nfunction withSubstitutions(day) {\n  return {\n    ...day,\n    exercises: day.exercises.map((exercise) => substituteExercise(exercise, state.profile.equipment)),\n    finisher: day.finisher ? substituteExercise(day.finisher, state.profile.equipment) : null\n  };\n}\n\nfunction currentProgramDay() {\n  const start = new Date(`${state.profile.startDate}T00:00:00`);\n  const today = new Date();\n  const diff = Math.floor((today - start) / 86400000) + 1;\n  return Math.max(1, Math.min(365, diff));\n}\n\nfunction navButton(id, label) {\n  return `<button data-route=\"${id}\" class=\"${route === id ? \"active\" : \"\"}\">${label}</button>`;\n}\n\nfunction sectionList(title, items) {\n  return `<article class=\"compact\"><h3>${title}</h3><ul>${items.map((item) => `<li>${item}</li>`).join(\"\")}</ul></article>`;\n}\n\nfunction rangeField(name, label, value, min, max) {\n  return `<label class=\"field mini\">${label}<input type=\"range\" name=\"${name}\" min=\"${min}\" max=\"${max}\" value=\"${value}\" /><span>${value}</span></label>`;\n}\n\nfunction metric(label, value) {\n  return `<article><span>${label}</span><strong>${value}</strong></article>`;\n}\n\nfunction bonusPill(label, xp, earned) {\n  return `<span class=\"${earned ? \"earned\" : \"\"}\"><b>${label}</b><small>${earned ? \"earned\" : xp}</small></span>`;\n}\n\nfunction cap(value) {\n  return value.charAt(0).toUpperCase() + value.slice(1);\n}\n\nfunction download(content, filename, type) {\n  const blob = new Blob([content], { type });\n  const url = URL.createObjectURL(blob);\n  const link = document.createElement(\"a\");\n  link.href = url;\n  link.download = filename;\n  link.click();\n  URL.revokeObjectURL(url);\n}\n"},"/src/program.js":{"contentType":"text/javascript; charset=utf-8","body":"export const SKILLS = [\"strength\", \"push\", \"pull\", \"legs\", \"core\", \"mobility\", \"athleticism\", \"recovery\"];\n\nexport const exerciseLibrary = {\n  \"Active Hang\": item(\"Active Hang\", \"pull\", [\"pull-up bar\"], \"Hold an active shoulder position without shrugging.\", \"Dead hang\", \"Scapular pull-up\", [\"Band lat pulldown\", \"Towel isometric pull\"]),\n  \"Assisted Pull-Up\": item(\"Assisted Pull-Up\", \"pull\", [\"pull-up bar\", \"resistance bands\"], \"Pull smoothly and stop one or two reps before failure.\", \"Ring row\", \"Strict pull-up\", [\"Ring row\", \"Table row\"]),\n  \"Band Face Pull\": item(\"Band Face Pull\", \"shoulder\", [\"resistance bands\"], \"Pull toward the face with elbows high and ribs down.\", \"Prone Y raise\", \"Slower tempo face pull\", [\"Prone Y raise\"]),\n  \"Broad Jump\": item(\"Broad Jump\", \"athleticism\", [], \"Land quietly with knees tracking over toes.\", \"Low squat jump\", \"Repeated broad jumps\", [\"Low pogo jump\"]),\n  \"Bulgarian Split Squat\": item(\"Bulgarian Split Squat\", \"legs\", [\"chair\"], \"Control the descent and keep the front foot rooted.\", \"Split squat\", \"Rear-foot-elevated split squat with pause\", [\"Split squat\", \"Step-up\"]),\n  \"Calf Raise\": item(\"Calf Raise\", \"legs\", [\"stairs\"], \"Pause at the top and lower under control.\", \"Floor calf raise\", \"Single-leg calf raise\", [\"Floor calf raise\"]),\n  \"Copenhagen Plank\": item(\"Copenhagen Plank\", \"core\", [\"chair\"], \"Keep hips tall and adductors engaged.\", \"Bent-knee Copenhagen\", \"Long-lever Copenhagen\", [\"Side plank adductor squeeze\"]),\n  \"Dead Bug\": item(\"Dead Bug\", \"core\", [], \"Exhale fully and keep the low back quiet.\", \"Heel taps\", \"Hollow body hold\", [\"Heel taps\"]),\n  \"Dead Hang\": item(\"Dead Hang\", \"pull\", [\"pull-up bar\"], \"Relax the body while keeping pain-free shoulders.\", \"Feet-assisted hang\", \"Active hang\", [\"Towel shoulder traction\"]),\n  \"Hollow Hold\": item(\"Hollow Hold\", \"core\", [], \"Press low back down and breathe behind the brace.\", \"Dead bug\", \"Long hollow hold\", [\"Dead bug\"]),\n  \"Jump Rope\": item(\"Jump Rope\", \"athleticism\", [\"jump rope\"], \"Stay tall and bounce lightly through the ankles.\", \"Marching\", \"Double-under practice\", [\"Low pogo jump\", \"Jumping jack\"]),\n  \"L-Sit Tuck\": item(\"L-Sit Tuck\", \"core\", [\"rings\"], \"Push the support away and keep the knees high.\", \"Seated knee lift\", \"One-leg L-sit\", [\"Chair support hold\"]),\n  \"Lateral Bound\": item(\"Lateral Bound\", \"athleticism\", [], \"Stick each landing before the next rep.\", \"Side step and hold\", \"Continuous skater bounds\", [\"Lateral step-down\"]),\n  \"Mobility Flow\": item(\"Mobility Flow\", \"mobility\", [], \"Move slowly through hips, ankles, t-spine, and shoulders.\", \"Shorter flow\", \"Longer flow\", [\"Breathing reset\"]),\n  \"Nordic Regression\": item(\"Nordic Regression\", \"legs\", [], \"Keep hips open and use hands before form breaks.\", \"Hamstring walkout\", \"Longer eccentric Nordic\", [\"Hamstring bridge\"]),\n  \"Pistol Squat Box\": item(\"Pistol Squat Box\", \"legs\", [\"chair\"], \"Sit back to the box with a controlled knee line.\", \"Step-down\", \"Lower box pistol\", [\"Split squat\"]),\n  \"Plank\": item(\"Plank\", \"core\", [], \"Squeeze glutes and breathe without sagging.\", \"Knee plank\", \"Long-lever plank\", [\"Dead bug\"]),\n  \"Plyo Push-Up\": item(\"Plyo Push-Up\", \"push\", [], \"Push explosively and land with soft elbows.\", \"Fast push-up\", \"Clap push-up\", [\"Incline fast push-up\"]),\n  \"Push-Up\": item(\"Push-Up\", \"push\", [], \"Keep a straight body line and full control.\", \"Incline push-up\", \"Ring push-up\", [\"Incline push-up\"]),\n  \"Ring Dip Progression\": item(\"Ring Dip Progression\", \"push\", [\"rings\"], \"Use stable shoulders and stop before deep discomfort.\", \"Bench dip\", \"Strict ring dip\", [\"Push-up\", \"Support hold\"]),\n  \"Ring Row\": item(\"Ring Row\", \"pull\", [\"rings\"], \"Pull the rings to the ribs and keep the body rigid.\", \"Table row\", \"Feet-elevated ring row\", [\"Table row\", \"Band row\"]),\n  \"Ring Support Hold\": item(\"Ring Support Hold\", \"push\", [\"rings\"], \"Turn rings slightly out and press tall.\", \"Chair support hold\", \"Ring dip negative\", [\"Push-up plank hold\"]),\n  \"Scapular Pull-Up\": item(\"Scapular Pull-Up\", \"pull\", [\"pull-up bar\"], \"Move only the shoulder blades.\", \"Active hang\", \"Pull-up\", [\"Band scapular pulldown\"]),\n  \"Scapular Push-Up\": item(\"Scapular Push-Up\", \"shoulder\", [], \"Reach the floor away without bending elbows.\", \"Wall scap push-up\", \"Feet-elevated scap push-up\", [\"Wall scap push-up\"]),\n  \"Shuttle Start\": item(\"Shuttle Start\", \"athleticism\", [], \"Accelerate for a few steps, then decelerate cleanly.\", \"Fast march\", \"Longer shuttle\", [\"Low pogo jump\"]),\n  \"Side Plank\": item(\"Side Plank\", \"core\", [], \"Stack ribs and pelvis while pushing the floor away.\", \"Bent-knee side plank\", \"Star side plank\", [\"Suitcase hold placeholder\"]),\n  \"Single-Leg RDL\": item(\"Single-Leg RDL\", \"legs\", [], \"Hinge from the hip and keep the pelvis square.\", \"Kickstand RDL\", \"Reach-loaded single-leg RDL\", [\"Hip airplane hold\"]),\n  \"Skater Hop\": item(\"Skater Hop\", \"athleticism\", [], \"Move laterally and own the landing.\", \"Lateral step\", \"Long skater hop\", [\"Lateral bound stick\"]),\n  \"Split Squat\": item(\"Split Squat\", \"legs\", [], \"Keep pressure through the full front foot.\", \"Assisted split squat\", \"Bulgarian split squat\", [\"Step-up\"]),\n  \"Strict Pull-Up\": item(\"Strict Pull-Up\", \"pull\", [\"pull-up bar\"], \"Start from active shoulders and pull chest toward the bar.\", \"Band-assisted pull-up\", \"Chest-to-bar pull-up\", [\"Ring row\", \"Table row\"]),\n  \"Wall Handstand Hold\": item(\"Wall Handstand Hold\", \"push\", [\"wall\"], \"Push tall and keep ribs tucked.\", \"Pike hold\", \"Longer wall hold\", [\"Pike plank\"]),\n  \"Walking\": item(\"Walking\", \"recovery\", [], \"Keep it easy enough to nasal breathe.\", \"Short walk\", \"Longer walk\", [\"Easy marching\"])\n};\n\nexport function generateProgram(startDate = todayIso()) {\n  const days = [];\n  for (let dayNumber = 1; dayNumber <= 365; dayNumber += 1) {\n    const block = Math.min(13, Math.floor((dayNumber - 1) / 28) + 1);\n    const dayInBlock = block === 13 ? dayNumber - 336 : ((dayNumber - 1) % 28) + 1;\n    const weekInBlock = Math.min(4, Math.floor((dayInBlock - 1) / 7) + 1);\n    const weekday = (dayNumber - 1) % 7;\n    const phase = phaseForDay(dayNumber);\n    const template = templates[weekday];\n    const intensity = weekInBlock === 1 ? 0 : weekInBlock === 2 ? 1 : weekInBlock === 3 ? 2 : -1;\n    const blockBonus = Math.floor((block - 1) / 2);\n    const isBenchmark = dayNumber % 84 === 0 || dayNumber === 365;\n    const date = addDays(startDate, dayNumber - 1);\n    days.push({\n      dayNumber,\n      date,\n      block,\n      weekInBlock,\n      phase,\n      title: isBenchmark ? \"Benchmark and reset\" : template.title,\n      focus: isBenchmark ? \"Measure key qualities without forcing max fatigue\" : template.focus,\n      duration: weekday >= 5 || weekInBlock === 4 ? 22 : 28,\n      difficulty: weekInBlock === 4 ? 2 : Math.min(5, 2 + intensity + Math.floor(block / 5)),\n      type: isBenchmark ? \"benchmark\" : weekInBlock === 4 || weekday === 3 || weekday === 6 ? \"recovery\" : \"training\",\n      equipment: unique(template.exercises.flatMap((name) => exerciseLibrary[name].equipment)),\n      warmup: warmupFor(weekday),\n      exercises: template.exercises.map((name, index) => prescribe(name, weekday, intensity, blockBonus, index, isBenchmark)),\n      finisher: template.finisher && weekInBlock !== 4 ? prescribe(template.finisher, weekday, intensity, blockBonus, 9, false) : null,\n      cooldown: [\"90 seconds easy breathing\", \"Hip flexor stretch 45 sec per side\", \"Shoulder or ankle mobility as needed\"],\n      notes: isBenchmark\n        ? \"Test clean reps only. Stop any test when form changes or pain appears.\"\n        : weekInBlock === 4\n          ? \"Deload week: leave extra reps in reserve and finish fresher than you started.\"\n          : \"Most strength work should finish with 1-3 repetitions in reserve.\",\n      recovery: weekday === 6 ? \"Keep this very easy. Recovery work earns progress too.\" : \"Adjust volume down if readiness is low.\"\n    });\n  }\n  return days;\n}\n\nexport function xpForExercise(exercise, log = {}) {\n  const category = exerciseLibrary[exercise.name]?.category || exercise.category;\n  const setCount = Number(exercise.sets || 1);\n  const difficulty = Number(log.difficulty || 3);\n  const pain = Number(log.pain || 0);\n  const formGood = log.formGood !== false;\n  const base = category === \"athleticism\" ? 12 : category === \"recovery\" || category === \"mobility\" ? 8 : 10;\n  let xp = base + setCount * 5 + Math.max(0, exercise.levelWeight || 0) * 4;\n  xp *= difficulty <= 2 ? 1.08 : difficulty >= 5 ? 0.85 : 1;\n  xp *= formGood ? 1 : 0.75;\n  xp *= pain >= 5 ? 0.35 : pain >= 3 ? 0.7 : 1;\n  return Math.max(3, Math.round(xp));\n}\n\nexport function skillsForExercise(name) {\n  const category = exerciseLibrary[name]?.category || \"strength\";\n  const map = {\n    pull: [\"pull\", \"strength\"],\n    push: [\"push\", \"strength\"],\n    legs: [\"legs\", \"strength\"],\n    core: [\"core\"],\n    mobility: [\"mobility\", \"recovery\"],\n    recovery: [\"recovery\"],\n    shoulder: [\"mobility\", \"push\"],\n    athleticism: [\"athleticism\", \"legs\"]\n  };\n  return map[category] || [\"strength\"];\n}\n\nexport function levelFromXp(xp) {\n  let level = 1;\n  while (xp >= xpForLevel(level + 1)) level += 1;\n  return level;\n}\n\nexport function xpForLevel(level) {\n  return Math.floor(80 * Math.pow(level - 1, 1.72));\n}\n\nexport function validateProgram(days) {\n  const errors = [];\n  if (days.length !== 365) errors.push(\"Program must contain exactly 365 days.\");\n  if (new Set(days.map((d) => d.dayNumber)).size !== days.length) errors.push(\"Day numbers must be unique.\");\n  days.forEach((day) => {\n    if (!day.duration) errors.push(`Day ${day.dayNumber} is missing duration.`);\n    if (!day.warmup?.length || !day.cooldown?.length) errors.push(`Day ${day.dayNumber} is missing warmup or cooldown.`);\n    day.exercises.forEach((exercise) => {\n      if (!exerciseLibrary[exercise.name]) errors.push(`Day ${day.dayNumber} references missing exercise ${exercise.name}.`);\n    });\n  });\n  for (let i = 1; i < days.length; i += 1) {\n    if (days[i].type === \"training\" && days[i - 1].focus.includes(\"jumps\") && days[i].focus.includes(\"jumps\")) {\n      errors.push(`Back-to-back high intensity plyometrics near day ${days[i].dayNumber}.`);\n    }\n  }\n  return errors;\n}\n\nfunction item(name, category, equipment, cue, regression, progression, alternatives) {\n  return {\n    name,\n    category,\n    equipment,\n    cue,\n    regression,\n    progression,\n    alternatives,\n    description: cue,\n    mistakes: \"Rushing reps, ignoring pain, and letting positions collapse.\",\n    qualities: [category, category === \"athleticism\" ? \"explosiveness\" : \"control\"]\n  };\n}\n\nconst templates = [\n  { title: \"Pull strength and core\", focus: \"Upper-body pull strength and trunk control\", exercises: [\"Active Hang\", \"Scapular Pull-Up\", \"Ring Row\", \"Assisted Pull-Up\", \"Dead Bug\", \"Side Plank\"], finisher: \"Dead Hang\" },\n  { title: \"Single-leg resilience\", focus: \"Single-leg strength, knees, ankles, calves, and groin\", exercises: [\"Split Squat\", \"Single-Leg RDL\", \"Calf Raise\", \"Copenhagen Plank\", \"Pistol Squat Box\"], finisher: \"Walking\" },\n  { title: \"Push strength and shoulders\", focus: \"Upper-body push strength and shoulder stability\", exercises: [\"Scapular Push-Up\", \"Push-Up\", \"Ring Support Hold\", \"Band Face Pull\", \"Plank\"], finisher: \"Ring Dip Progression\" },\n  { title: \"Mobility and recovery\", focus: \"Mobility, recovery, and low-intensity core\", exercises: [\"Mobility Flow\", \"Dead Bug\", \"Side Plank\", \"Walking\"], finisher: null },\n  { title: \"Full-body calisthenics\", focus: \"Full-body strength and skill practice\", exercises: [\"Strict Pull-Up\", \"Bulgarian Split Squat\", \"Ring Dip Progression\", \"Hollow Hold\", \"L-Sit Tuck\"], finisher: \"Wall Handstand Hold\" },\n  { title: \"Athletic conditioning\", focus: \"Athletic conditioning, jumps, lateral movement, agility\", exercises: [\"Jump Rope\", \"Broad Jump\", \"Lateral Bound\", \"Skater Hop\", \"Shuttle Start\"], finisher: \"Mobility Flow\" },\n  { title: \"Active recovery\", focus: \"Walking, mobility, breathing, and light movement\", exercises: [\"Walking\", \"Mobility Flow\", \"Dead Hang\"], finisher: null }\n];\n\nfunction prescribe(name, weekday, intensity, blockBonus, index, isBenchmark) {\n  const lib = exerciseLibrary[name];\n  const hard = Math.max(0, intensity + blockBonus);\n  const isHold = [\"Active Hang\", \"Dead Hang\", \"Plank\", \"Side Plank\", \"Hollow Hold\", \"L-Sit Tuck\", \"Wall Handstand Hold\", \"Copenhagen Plank\"].includes(name);\n  const isMobility = lib.category === \"mobility\" || lib.category === \"recovery\";\n  const isJump = lib.category === \"athleticism\";\n  const sets = isBenchmark ? 2 : isMobility ? 1 : isJump ? 3 : Math.min(5, 2 + Math.max(0, intensity) + (index < 3 ? 1 : 0));\n  const reps = isHold ? `${20 + hard * 5}-${35 + hard * 6} sec` : isMobility ? `${8 + hard * 2}-${12 + hard * 2} min` : isJump ? `${3 + Math.min(2, hard)} quality reps` : `${6 + hard}-${10 + hard * 2}`;\n  return {\n    name,\n    category: lib.category,\n    sets,\n    reps,\n    restSeconds: isMobility ? 30 : isJump ? 75 : 60 + Math.min(60, hard * 10),\n    tempo: isJump || isMobility ? \"controlled\" : intensity >= 2 ? \"31X1\" : \"2111\",\n    targetRIR: isMobility ? null : isJump ? 4 : Math.max(1, 3 - Math.min(2, intensity)),\n    cue: lib.cue,\n    regression: lib.regression,\n    progression: lib.progression,\n    alternatives: lib.alternatives,\n    equipment: lib.equipment,\n    levelWeight: hard\n  };\n}\n\nfunction warmupFor(weekday) {\n  const common = [\"2 min easy pulse raiser\", \"Joint circles from ankles to shoulders\", \"2 rounds of 5 slow squats and 5 scapular reps\"];\n  if (weekday === 5) return [\"3 min easy rope or marching\", \"Ankle pogo prep\", \"Lateral shuffle rehearsal\"];\n  if (weekday === 3 || weekday === 6) return [\"Easy nasal breathing\", \"Gentle hip and t-spine mobility\", \"Shoulder CARs\"];\n  return common;\n}\n\nfunction phaseForDay(day) {\n  if (day <= 84) return \"Foundation\";\n  if (day <= 168) return \"Strength\";\n  if (day <= 252) return \"Athletic performance\";\n  return \"Mastery and longevity\";\n}\n\nfunction addDays(startIso, offset) {\n  const date = new Date(`${startIso}T00:00:00`);\n  date.setDate(date.getDate() + offset);\n  return date.toISOString().slice(0, 10);\n}\n\nexport function todayIso() {\n  return new Date().toISOString().slice(0, 10);\n}\n\nfunction unique(values) {\n  return [...new Set(values)];\n}\n"},"/src/state.js":{"contentType":"text/javascript; charset=utf-8","body":"import { SKILLS, generateProgram, skillsForExercise, xpForExercise, levelFromXp, todayIso } from \"./program.js\";\n\nconst KEY = \"athlete365-state-v1\";\n\nexport function initialState() {\n  const startDate = todayIso();\n  return {\n    profile: {\n      name: \"\",\n      level: \"Intermediate\",\n      startDate,\n      equipment: [\"pull-up bar\", \"rings\", \"resistance bands\", \"jump rope\", \"chair\", \"stairs\"],\n      sessionDuration: 30,\n      units: \"metric\",\n      theme: \"dark\",\n      limitations: \"\"\n    },\n    xp: Object.fromEntries(SKILLS.map((skill) => [skill, 0])),\n    microTasks: [],\n    microTaskHistory: [],\n    taskCompletions: {},\n    streakBonuses: {},\n    completedSets: {},\n    workouts: {},\n    exerciseLogs: {},\n    records: [],\n    achievements: []\n  };\n}\n\nexport function isSignedIn(state) {\n  return Boolean(state.profile.name?.trim());\n}\n\nexport function signIn(state, username) {\n  const next = structuredClone(state);\n  next.profile.name = username.trim();\n  return ensureMicroTasks(next);\n}\n\nexport function signOut(state) {\n  const next = structuredClone(state);\n  next.profile.name = \"\";\n  return next;\n}\n\nexport function loadState() {\n  try {\n    const loaded = { ...initialState(), ...JSON.parse(localStorage.getItem(KEY) || \"{}\") };\n    return ensureMicroTasks(loaded);\n  } catch {\n    return ensureMicroTasks(initialState());\n  }\n}\n\nexport function saveState(state) {\n  localStorage.setItem(KEY, JSON.stringify(state));\n}\n\nexport function resetState() {\n  localStorage.removeItem(KEY);\n}\n\nexport function programForState(state) {\n  return generateProgram(state.profile.startDate);\n}\n\nexport const microTaskPool = [\n  tierTask(1, \"10 Push-Ups\", \"Complete 10 clean push-ups. Use an incline if needed.\", 18, [\"push\", \"strength\"]),\n  tierTask(1, \"10 Sit-Ups\", \"Complete 10 controlled sit-ups or crunches.\", 14, [\"core\"]),\n  tierTask(1, \"15 Squats\", \"Complete 15 bodyweight squats with full-foot pressure.\", 16, [\"legs\"]),\n  tierTask(1, \"20-Second Plank\", \"Hold a strong plank for 20 seconds.\", 14, [\"core\"]),\n  tierTask(1, \"10 Reverse Lunges\", \"Complete 5 reverse lunges per side.\", 16, [\"legs\"]),\n  tierTask(1, \"20 Calf Raises\", \"Complete 20 controlled calf raises.\", 14, [\"legs\"]),\n  tierTask(1, \"30-Second Mobility Reset\", \"Open hips, ankles, and shoulders for 30 seconds.\", 10, [\"mobility\", \"recovery\"]),\n  tierTask(1, \"10 Glute Bridges\", \"Complete 10 glute bridges with a pause at the top.\", 12, [\"legs\", \"core\"]),\n  tierTask(1, \"20 Mountain Climbers\", \"Complete 10 reps per side at a steady pace.\", 15, [\"core\", \"athleticism\"]),\n  tierTask(1, \"10 Scapular Push-Ups\", \"Move only your shoulder blades.\", 12, [\"push\", \"mobility\"]),\n  tierTask(2, \"3 Rounds: 8 Push-Ups + 12 Squats\", \"Move steadily and stop before form breaks.\", 45, [\"push\", \"legs\", \"strength\"]),\n  tierTask(2, \"2 Rounds: 20s Plank + 10 Sit-Ups\", \"Brace hard and keep reps controlled.\", 36, [\"core\"]),\n  tierTask(2, \"20 Split Squats\", \"Complete 10 reps per side.\", 34, [\"legs\", \"strength\"]),\n  tierTask(2, \"60-Second Mobility Flow\", \"Move through hips, t-spine, ankles, and shoulders.\", 25, [\"mobility\", \"recovery\"]),\n  tierTask(2, \"30 Low Pogo Jumps\", \"Bounce lightly and quietly through the ankles.\", 35, [\"athleticism\", \"legs\"]),\n  tierTask(2, \"3 Rounds: 10 Calf Raises + 10 Tibialis Raises\", \"Build lower-leg capacity.\", 38, [\"legs\", \"recovery\"]),\n  tierTask(2, \"Chair Step-Ups\", \"Complete 10 controlled step-ups per side.\", 42, [\"legs\", \"strength\"], [\"chair\"]),\n  tierTask(3, \"5-Minute Bodyweight Circuit\", \"Cycle push-ups, squats, sit-ups, and plank until time ends.\", 80, [\"strength\", \"core\", \"legs\", \"push\"]),\n  tierTask(3, \"4 Rounds: 6 Push-Ups + 8 Lunges\", \"Keep every rep clean.\", 70, [\"push\", \"legs\", \"strength\"]),\n  tierTask(3, \"90-Second Core Block\", \"Alternate hollow hold, side plank, and dead bug.\", 62, [\"core\"]),\n  tierTask(3, \"Skater Hop Practice\", \"Complete 3 x 6 controlled side-to-side hops.\", 65, [\"athleticism\", \"legs\"]),\n  tierTask(3, \"Pull-Up Bar Hang\", \"Accumulate 60 seconds of hanging.\", 58, [\"pull\", \"recovery\"], [\"pull-up bar\"]),\n  tierTask(4, \"10-Minute Density Block\", \"Rotate push-ups, squats, and core with perfect form.\", 140, [\"strength\", \"push\", \"legs\", \"core\"]),\n  tierTask(4, \"Advanced Leg Control\", \"3 rounds of split squats, calf raises, and skater holds.\", 120, [\"legs\", \"athleticism\"]),\n  tierTask(4, \"Ring Row Mini-Workout\", \"4 x 8 ring rows with 60 seconds rest.\", 110, [\"pull\", \"strength\"], [\"rings\"]),\n  tierTask(4, \"Explosive Push-Up Practice\", \"5 x 3 fast push-ups with soft landings.\", 105, [\"push\", \"athleticism\"])\n];\n\nexport function ensureMicroTasks(state) {\n  const next = { ...state };\n  next.microTasks = Array.isArray(next.microTasks) ? [...next.microTasks] : [];\n  next.microTaskHistory = Array.isArray(next.microTaskHistory) ? [...next.microTaskHistory] : [];\n  while (next.microTasks.length < 8) {\n    next.microTasks.push(drawMicroTask(next, next.microTasks.length));\n  }\n  return next;\n}\n\nexport function completeMicroTask(state, slotIndex) {\n  const next = structuredClone(ensureMicroTasks(state));\n  const task = next.microTasks[slotIndex];\n  if (!task) return next;\n  next.microTaskHistory.unshift({\n    ...task,\n    completedAt: new Date().toISOString()\n  });\n  next.microTaskHistory = next.microTaskHistory.slice(0, 250);\n  awardXp(next, task.skills, task.xp);\n  next.microTasks[slotIndex] = drawMicroTask(next, slotIndex + next.microTaskHistory.length);\n  next.achievements = achievementsFor(next, programForState(next));\n  return next;\n}\n\nexport function completeWorkout(state, day, form) {\n  const next = structuredClone(state);\n  const workoutKey = String(day.dayNumber);\n  if (next.workouts[workoutKey]?.completed) return next;\n  let gained = 0;\n  day.exercises.concat(day.finisher ? [day.finisher] : []).forEach((exercise, index) => {\n    const log = {\n      difficulty: Number(form.get(`difficulty-${index}`) || 3),\n      pain: Number(form.get(`pain-${index}`) || 0),\n      formGood: form.get(`form-${index}`) !== \"off\"\n    };\n    const xp = xpForExercise(exercise, log);\n    gained += xp;\n    skillsForExercise(exercise.name).forEach((skill) => {\n      next.xp[skill] = (next.xp[skill] || 0) + Math.round(xp / skillsForExercise(exercise.name).length);\n    });\n  });\n  if (day.type === \"recovery\") next.xp.recovery += 25;\n  if (day.type === \"benchmark\") next.xp.athleticism += 75;\n  const workoutBonus = day.type === \"benchmark\" ? 220 : day.type === \"recovery\" ? 90 : 160;\n  gained += workoutBonus;\n  awardXp(next, [\"strength\", \"recovery\"], workoutBonus);\n  next.taskCompletions[`day-${day.dayNumber}:full-workout`] = true;\n  next.workouts[workoutKey] = {\n    completed: true,\n    date: new Date().toISOString(),\n    energy: Number(form.get(\"energy\") || 3),\n    sleep: Number(form.get(\"sleep\") || 3),\n    soreness: Number(form.get(\"soreness\") || 2),\n    jointPain: Number(form.get(\"jointPain\") || 0),\n    bodyweight: form.get(\"bodyweight\") || \"\",\n    notes: form.get(\"notes\") || \"\",\n    gained\n  };\n  next.achievements = achievementsFor(next, programForState(next));\n  return next;\n}\n\nexport function dailyTasksFor(day) {\n  const tasks = [\n    {\n      id: \"readiness\",\n      title: \"Log readiness\",\n      detail: \"Energy, sleep, soreness, joint discomfort\",\n      xp: 15,\n      skills: [\"recovery\"]\n    },\n    {\n      id: \"warmup\",\n      title: \"Complete warm-up\",\n      detail: day.warmup.slice(0, 2).join(\" + \"),\n      xp: 25,\n      skills: [\"mobility\", \"recovery\"]\n    }\n  ];\n  day.exercises.slice(0, 5).forEach((exercise, index) => {\n    tasks.push({\n      id: `exercise-${index}`,\n      title: exercise.name,\n      detail: `${exercise.sets} x ${exercise.reps}`,\n      xp: xpForExercise(exercise),\n      skills: skillsForExercise(exercise.name),\n      exercise\n    });\n  });\n  if (day.finisher) {\n    tasks.push({\n      id: \"finisher\",\n      title: `Optional finisher: ${day.finisher.name}`,\n      detail: `${day.finisher.sets} x ${day.finisher.reps}`,\n      xp: Math.max(20, Math.round(xpForExercise(day.finisher) * 0.8)),\n      skills: skillsForExercise(day.finisher.name),\n      exercise: day.finisher\n    });\n  } else {\n    tasks.push({\n      id: \"easy-extra\",\n      title: \"Easy extra movement\",\n      detail: \"5-10 minutes walking, mobility, or breathing\",\n      xp: 25,\n      skills: [\"recovery\", \"mobility\"]\n    });\n  }\n  tasks.push({\n    id: \"cooldown\",\n    title: \"Cooldown and breathing\",\n    detail: day.cooldown.slice(0, 2).join(\" + \"),\n    xp: 25,\n    skills: [\"mobility\", \"recovery\"]\n  });\n  tasks.push({\n    id: \"full-workout\",\n    title: \"Complete the full workout\",\n    detail: `${day.title} · ${day.duration} minutes`,\n    xp: day.type === \"benchmark\" ? 220 : day.type === \"recovery\" ? 90 : 160,\n    skills: day.type === \"recovery\" ? [\"recovery\", \"mobility\"] : [\"strength\", \"athleticism\"],\n    featured: true\n  });\n  return tasks.slice(0, 10);\n}\n\nexport function completeTask(state, day, taskId) {\n  const next = structuredClone(state);\n  const key = taskKey(day.dayNumber, taskId);\n  if (next.taskCompletions[key]) return next;\n  const tasks = dailyTasksFor(day);\n  const task = tasks.find((item) => item.id === taskId);\n  if (!task) return next;\n  next.taskCompletions[key] = {\n    completed: true,\n    date: new Date().toISOString(),\n    xp: task.xp\n  };\n  awardXp(next, task.skills, task.xp);\n  if (taskId === \"full-workout\" && !next.workouts[String(day.dayNumber)]?.completed) {\n    next.workouts[String(day.dayNumber)] = {\n      completed: true,\n      date: new Date().toISOString(),\n      energy: 3,\n      sleep: 3,\n      soreness: 2,\n      jointPain: 0,\n      bodyweight: \"\",\n      notes: \"Completed from task list.\",\n      gained: task.xp\n    };\n  }\n  awardTaskStreakBonus(next, programForState(next), day.dayNumber);\n  next.achievements = achievementsFor(next, programForState(next));\n  return next;\n}\n\nexport function taskProgress(state, day) {\n  const tasks = dailyTasksFor(day);\n  const completed = tasks.filter((task) => state.taskCompletions[taskKey(day.dayNumber, task.id)]).length;\n  return {\n    total: tasks.length,\n    completed,\n    percent: Math.round((completed / tasks.length) * 100)\n  };\n}\n\nexport function toggleSet(state, dayNumber, exerciseIndex, setIndex) {\n  const next = structuredClone(state);\n  const key = `${dayNumber}:${exerciseIndex}:${setIndex}`;\n  next.completedSets[key] = !next.completedSets[key];\n  return next;\n}\n\nexport function stats(state, program) {\n  const completed = Object.values(state.workouts).filter((w) => w.completed);\n  const completedTasks = Object.values(state.taskCompletions || {}).filter(Boolean);\n  const microTasksDone = (state.microTaskHistory || []).length;\n  const totalXp = Object.values(state.xp).reduce((sum, value) => sum + value, 0);\n  return {\n    completedCount: completed.length,\n    completedTaskCount: completedTasks.length,\n    microTasksDone,\n    completionRate: Math.round((completed.length / program.length) * 100),\n    totalXp,\n    totalLevel: Object.values(state.xp).reduce((sum, value) => sum + levelFromXp(value), 0),\n    streak: streak(state, program),\n    taskStreak: taskStreak(state, program),\n    minutes: completed.length * 25\n  };\n}\n\nexport function readinessAdvice(workout, readiness) {\n  const score = Number(readiness.energy) + Number(readiness.sleep) - Number(readiness.soreness);\n  if (Number(readiness.jointPain) >= 5) return \"Significant discomfort: choose pain-free alternatives and stop painful movements.\";\n  if (score >= 6) return \"High readiness: use the normal workout.\";\n  if (score >= 3) return \"Medium readiness: remove the finisher or one accessory set.\";\n  return workout.type === \"training\"\n    ? \"Low readiness: reduce volume by 30-50% and replace explosive work with mobility.\"\n    : \"Low readiness: keep the recovery session very easy.\";\n}\n\nexport function substituteExercise(exercise, equipment) {\n  const missing = exercise.equipment.filter((item) => !equipment.includes(item));\n  if (!missing.length) return exercise;\n  return { ...exercise, substituted: true, originalName: exercise.name, name: exercise.alternatives[0] || exercise.regression, missing };\n}\n\nexport function exportJson(state) {\n  return JSON.stringify({ exportedAt: new Date().toISOString(), state }, null, 2);\n}\n\nexport function exportCsv(state) {\n  const rows = [[\"day\", \"completed_at\", \"energy\", \"sleep\", \"soreness\", \"joint_pain\", \"bodyweight\", \"xp\", \"notes\"]];\n  Object.entries(state.workouts).forEach(([day, workout]) => {\n    rows.push([day, workout.date, workout.energy, workout.sleep, workout.soreness, workout.jointPain, workout.bodyweight, workout.gained, JSON.stringify(workout.notes || \"\")]);\n  });\n  return rows.map((row) => row.join(\",\")).join(\"\\n\");\n}\n\nexport function taskKey(dayNumber, taskId) {\n  return `day-${dayNumber}:${taskId}`;\n}\n\nexport function taskStreak(state, program) {\n  let count = 0;\n  for (const day of program) {\n    const progress = taskProgress(state, day);\n    if (progress.completed === progress.total) count += 1;\n    else if (new Date(day.date) < new Date(todayIso())) count = 0;\n  }\n  return count;\n}\n\nfunction awardXp(state, skills, xp) {\n  const share = Math.round(xp / skills.length);\n  skills.forEach((skill) => {\n    state.xp[skill] = (state.xp[skill] || 0) + share;\n  });\n}\n\nfunction tierTask(tier, title, detail, xp, skills, equipment = []) {\n  return { id: slug(title), tier, title, detail, xp, skills, equipment };\n}\n\nfunction drawMicroTask(state, salt) {\n  const available = microTaskPool.filter((task) => task.tier <= unlockedTier(state) && task.equipment.every((item) => state.profile.equipment.includes(item)));\n  const recentIds = new Set((state.microTaskHistory || []).slice(0, 6).map((task) => task.id));\n  const currentIds = new Set((state.microTasks || []).map((task) => task.id));\n  const filtered = available.filter((task) => !recentIds.has(task.id) && !currentIds.has(task.id));\n  const pool = filtered.length ? filtered : available;\n  const seed = Object.values(state.xp || {}).reduce((sum, value) => sum + value, 0) + salt * 17 + (state.microTaskHistory || []).length * 31;\n  return { ...pool[Math.abs(seed) % pool.length] };\n}\n\nfunction unlockedTier(state) {\n  const totalLevel = Object.values(state.xp || {}).reduce((sum, value) => sum + levelFromXp(value), 0);\n  if (totalLevel >= 80) return 4;\n  if (totalLevel >= 45) return 3;\n  if (totalLevel >= 20) return 2;\n  return 1;\n}\n\nfunction slug(value) {\n  return value.toLowerCase().replace(/[^a-z0-9]+/g, \"-\").replace(/(^-|-$)/g, \"\");\n}\n\nfunction awardTaskStreakBonus(state, program, dayNumber) {\n  const day = program[dayNumber - 1];\n  if (!day) return;\n  const progress = taskProgress(state, day);\n  if (progress.completed !== progress.total) return;\n  const streakNow = taskStreak(state, program);\n  const bonuses = { 3: 75, 7: 200, 14: 450, 30: 1200, 60: 2600, 100: 5000 };\n  const bonus = bonuses[streakNow];\n  if (!bonus || state.streakBonuses[`tasks-${streakNow}`]) return;\n  state.streakBonuses[`tasks-${streakNow}`] = {\n    date: new Date().toISOString(),\n    xp: bonus\n  };\n  awardXp(state, [\"recovery\", \"strength\"], bonus);\n}\n\nfunction streak(state, program) {\n  let count = 0;\n  for (const day of program) {\n    if (state.workouts[String(day.dayNumber)]?.completed) count += 1;\n    else if (new Date(day.date) < new Date(todayIso())) count = 0;\n  }\n  return count;\n}\n\nfunction achievementsFor(state, program) {\n  const current = new Set(state.achievements);\n  const s = stats(state, program);\n  if (s.completedCount >= 1) current.add(\"First workout logged\");\n  if (s.completedTaskCount >= 10) current.add(\"First task board cleared\");\n  if (s.microTasksDone >= 10) current.add(\"10 quick tasks complete\");\n  if (s.microTasksDone >= 50) current.add(\"50 quick tasks complete\");\n  if (s.completedCount >= 7) current.add(\"Seven sessions complete\");\n  if (s.completedCount >= 28) current.add(\"Block finisher\");\n  if (s.streak >= 7) current.add(\"Seven-day streak\");\n  if (s.taskStreak >= 3) current.add(\"Three-day task streak\");\n  if (s.taskStreak >= 7) current.add(\"One-week task streak\");\n  if (s.totalXp >= 2500) current.add(\"XP contender\");\n  return [...current];\n}\n"},"/src/styles.css":{"contentType":"text/css; charset=utf-8","body":":root {\n  color-scheme: dark;\n  --bg: #0f172a;\n  --panel: #172033;\n  --panel-2: #101827;\n  --text: #e5edf7;\n  --muted: #9aa7b8;\n  --line: #2a3549;\n  --brand: #14b8a6;\n  --brand-2: #f59e0b;\n  --danger: #fb7185;\n  --ok: #84cc16;\n  --shadow: 0 20px 50px rgba(0, 0, 0, 0.25);\n  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\n\n:root[data-theme=\"light\"] {\n  color-scheme: light;\n  --bg: #edf2f7;\n  --panel: #ffffff;\n  --panel-2: #f8fafc;\n  --text: #142033;\n  --muted: #5b687a;\n  --line: #d8e0ea;\n  --shadow: 0 18px 42px rgba(15, 23, 42, 0.11);\n}\n\n* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  background:\n    linear-gradient(135deg, rgba(20, 184, 166, 0.14), transparent 32rem),\n    linear-gradient(315deg, rgba(245, 158, 11, 0.1), transparent 28rem),\n    var(--bg);\n  color: var(--text);\n  min-height: 100vh;\n}\n\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n}\n\nbutton {\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  min-height: 42px;\n  padding: 0.65rem 0.9rem;\n  background: var(--panel-2);\n  color: var(--text);\n  cursor: pointer;\n}\n\nbutton:hover,\nbutton.active {\n  border-color: var(--brand);\n}\n\n.primary {\n  background: var(--brand);\n  color: #05211d;\n  border-color: var(--brand);\n  font-weight: 800;\n}\n\n.shell-header {\n  display: flex;\n  justify-content: space-between;\n  gap: 1rem;\n  align-items: end;\n  padding: 1.5rem clamp(1rem, 3vw, 2.5rem);\n  max-width: 1500px;\n  margin: 0 auto;\n}\n\n.shell-header h1 {\n  margin: 0.1rem 0 0;\n  font-size: clamp(1.7rem, 4vw, 3.5rem);\n  line-height: 1;\n}\n\nnav {\n  display: flex;\n  gap: 0.45rem;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n}\n\n.app-shell {\n  max-width: 1500px;\n  margin: 0 auto;\n  padding: 0 clamp(1rem, 3vw, 2.5rem) 2.5rem;\n}\n\n.login-shell {\n  min-height: 68vh;\n  display: grid;\n  place-items: center;\n}\n\n.login-card {\n  width: min(100%, 440px);\n  display: grid;\n  gap: 1rem;\n  background: color-mix(in srgb, var(--panel) 94%, transparent);\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  box-shadow: var(--shadow);\n  padding: clamp(1.2rem, 4vw, 2rem);\n}\n\n.login-card h2 {\n  margin-bottom: 0;\n}\n\n.hero-grid {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 360px;\n  gap: 1rem;\n  align-items: start;\n}\n\n.page-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 1rem;\n}\n\n.today-panel,\n.card,\n.compact,\n.readiness {\n  background: color-mix(in srgb, var(--panel) 94%, transparent);\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  box-shadow: var(--shadow);\n}\n\n.today-panel {\n  padding: clamp(1rem, 2.5vw, 1.5rem);\n}\n\n.card,\n.compact,\n.readiness {\n  padding: 1rem;\n}\n\n.span {\n  grid-column: 1 / -1;\n}\n\n.side-panel {\n  display: grid;\n  gap: 1rem;\n}\n\n.panel-head,\n.exercise-head {\n  display: flex;\n  justify-content: space-between;\n  gap: 1rem;\n  align-items: start;\n}\n\n.eyebrow {\n  color: var(--brand);\n  text-transform: uppercase;\n  letter-spacing: 0;\n  font-size: 0.72rem;\n  font-weight: 800;\n  margin: 0 0 0.35rem;\n}\n\nh2,\nh3,\np {\n  margin-top: 0;\n}\n\nh2 {\n  font-size: clamp(1.45rem, 2.5vw, 2.3rem);\n  margin-bottom: 0.35rem;\n}\n\nh3 {\n  margin-bottom: 0.55rem;\n}\n\np,\nli,\nsmall,\ndd {\n  color: var(--muted);\n  line-height: 1.5;\n}\n\n.level-badge {\n  display: inline-flex;\n  justify-content: center;\n  align-items: center;\n  min-width: 96px;\n  min-height: 42px;\n  border: 1px solid color-mix(in srgb, var(--brand) 60%, var(--line));\n  border-radius: 8px;\n  color: var(--brand);\n  background: rgba(20, 184, 166, 0.08);\n}\n\n.readiness {\n  display: grid;\n  grid-template-columns: 1.4fr repeat(5, minmax(92px, 1fr));\n  gap: 0.8rem;\n  margin: 1rem 0;\n  align-items: end;\n}\n\n.field {\n  display: grid;\n  gap: 0.35rem;\n  color: var(--muted);\n  font-size: 0.88rem;\n}\n\n.field input,\n.field select,\n.field textarea,\n#calendar-filter {\n  width: 100%;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel-2);\n  color: var(--text);\n  padding: 0.65rem 0.75rem;\n}\n\n.field.mini span {\n  color: var(--brand-2);\n  font-weight: 800;\n}\n\n.wide {\n  margin-top: 1rem;\n}\n\n.exercise-stack {\n  display: grid;\n  gap: 0.85rem;\n  margin: 1rem 0;\n}\n\n.task-summary {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) auto;\n  gap: 1rem;\n  align-items: center;\n  padding: 1rem;\n  margin: 1rem 0;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel-2);\n}\n\n.task-summary span {\n  display: block;\n  color: var(--muted);\n  font-size: 0.86rem;\n  margin-bottom: 0.45rem;\n}\n\n.task-summary strong {\n  color: var(--brand-2);\n}\n\n.task-list {\n  display: grid;\n  gap: 0.75rem;\n}\n\n.micro-task-list {\n  display: grid;\n  gap: 0.75rem;\n  margin-top: 1rem;\n}\n\n.planned-head {\n  display: flex;\n  justify-content: space-between;\n  gap: 1rem;\n  align-items: start;\n  border-top: 1px solid var(--line);\n  margin-top: 1.35rem;\n  padding-top: 1.2rem;\n}\n\n.task-card {\n  display: grid;\n  grid-template-columns: 52px minmax(0, 1fr) auto;\n  gap: 0.9rem;\n  align-items: center;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel-2);\n  padding: 0.85rem;\n}\n\n.task-card.featured {\n  border-color: color-mix(in srgb, var(--brand-2) 70%, var(--line));\n  background: linear-gradient(135deg, rgba(245, 158, 11, 0.12), var(--panel-2) 52%);\n}\n\n.task-card.micro {\n  background: color-mix(in srgb, var(--panel-2) 88%, var(--brand) 12%);\n}\n\n.task-card.micro.tier-2,\n.task-card.micro.tier-3,\n.task-card.micro.tier-4 {\n  background: color-mix(in srgb, var(--panel-2) 84%, var(--brand-2) 16%);\n}\n\n.task-card.done {\n  border-color: color-mix(in srgb, var(--ok) 70%, var(--line));\n}\n\n.task-card h3,\n.task-card p {\n  margin-bottom: 0.15rem;\n}\n\n.task-card > strong {\n  color: var(--brand);\n  white-space: nowrap;\n}\n\n.task-check {\n  width: 46px;\n  height: 46px;\n  padding: 0;\n  border-radius: 999px;\n  font-size: 1.4rem;\n  font-weight: 900;\n}\n\n.task-check:disabled {\n  cursor: default;\n  background: var(--ok);\n  color: #172006;\n  border-color: var(--ok);\n}\n\n.bonus-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 0.6rem;\n}\n\n.bonus-grid span {\n  display: grid;\n  gap: 0.15rem;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  padding: 0.65rem;\n  background: var(--panel-2);\n}\n\n.bonus-grid span.earned {\n  border-color: var(--ok);\n}\n\n.bonus-grid small {\n  color: var(--brand-2);\n}\n\n.exercise-card {\n  background: var(--panel-2);\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  padding: 1rem;\n}\n\n.exercise-card.subbed {\n  border-color: var(--brand-2);\n}\n\n.sub-note {\n  color: var(--brand-2);\n  margin-bottom: 0;\n}\n\ndl {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 0.5rem;\n  margin: 0.8rem 0;\n}\n\ndt {\n  color: var(--muted);\n  font-size: 0.75rem;\n}\n\ndd {\n  margin: 0;\n  color: var(--text);\n  font-weight: 700;\n}\n\n.set-row,\n.actions,\n.chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.55rem;\n}\n\n.secondary-actions {\n  margin-top: 0.7rem;\n}\n\n.set {\n  width: 44px;\n  padding: 0;\n}\n\n.set.done {\n  background: var(--ok);\n  color: #172006;\n  border-color: var(--ok);\n}\n\n.adjust-grid,\n.settings-grid,\n.check-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 0.8rem;\n  margin-top: 0.85rem;\n}\n\ndetails {\n  margin-top: 0.7rem;\n}\n\nsummary {\n  cursor: pointer;\n  color: var(--brand);\n}\n\n.metrics {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 0.7rem;\n}\n\n.metrics article {\n  background: var(--panel-2);\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  padding: 0.8rem;\n}\n\n.metrics span {\n  color: var(--muted);\n  display: block;\n  font-size: 0.82rem;\n}\n\n.metrics strong {\n  font-size: 1.55rem;\n}\n\n.skill-list {\n  display: grid;\n  gap: 0.7rem;\n}\n\n.skill-list span {\n  display: flex;\n  justify-content: space-between;\n  gap: 0.5rem;\n  align-items: baseline;\n  margin-bottom: 0.25rem;\n}\n\n.bar {\n  height: 9px;\n  background: var(--panel-2);\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  overflow: hidden;\n}\n\n.bar span {\n  display: block;\n  height: 100%;\n  background: linear-gradient(90deg, var(--brand), var(--brand-2));\n}\n\n.chips span {\n  border: 1px solid var(--line);\n  background: var(--panel-2);\n  border-radius: 999px;\n  padding: 0.35rem 0.55rem;\n  color: var(--muted);\n  font-size: 0.82rem;\n}\n\n.calendar-list {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 0.6rem;\n  margin-top: 1rem;\n  max-height: 70vh;\n  overflow: auto;\n  padding-right: 0.25rem;\n}\n\n.calendar-day {\n  text-align: left;\n  display: grid;\n  gap: 0.25rem;\n  align-content: start;\n  min-height: 112px;\n}\n\n.calendar-day span {\n  color: var(--brand);\n  font-size: 0.8rem;\n  font-weight: 800;\n}\n\n.calendar-day.complete {\n  border-color: var(--ok);\n}\n\n.calendar-day.current {\n  outline: 2px solid var(--brand);\n}\n\n.timeline p {\n  border-bottom: 1px solid var(--line);\n  padding-bottom: 0.55rem;\n}\n\n.warning {\n  border: 1px solid var(--danger);\n  color: var(--danger);\n  padding: 1rem;\n  border-radius: 8px;\n  margin-bottom: 1rem;\n  background: rgba(251, 113, 133, 0.08);\n}\n\n@media (max-width: 1100px) {\n  .hero-grid,\n  .page-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .readiness,\n  .calendar-list {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .side-panel {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n}\n\n@media (max-width: 720px) {\n  .shell-header {\n    display: grid;\n    align-items: start;\n  }\n\n  nav {\n    justify-content: start;\n    overflow-x: auto;\n    flex-wrap: nowrap;\n    padding-bottom: 0.2rem;\n  }\n\n  .readiness,\n  .adjust-grid,\n  .settings-grid,\n  .check-grid,\n  .calendar-list,\n  .side-panel,\n  .metrics,\n  .task-summary,\n  .task-card,\n  dl {\n    grid-template-columns: 1fr;\n  }\n\n  .panel-head,\n  .exercise-head,\n  .planned-head {\n    display: grid;\n  }\n\n  button {\n    min-height: 46px;\n  }\n}\n"},"/":{"contentType":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <meta\n      name=\"description\"\n      content=\"Athlete 365 is a local-first calisthenics training app with a 365-day plan, XP, levels, adaptive workouts, and progress tracking.\"\n    />\n    <title>Athlete 365</title>\n    <link rel=\"manifest\" href=\"./manifest.webmanifest\" />\n    <link rel=\"stylesheet\" href=\"./src/styles.css\" />\n  </head>\n  <body>\n    <div id=\"app\"></div>\n    <script type=\"module\" src=\"./src/app.js\"></script>\n  </body>\n</html>\n"}};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const path = url.pathname === "/" ? "/" : decodeURIComponent(url.pathname);
    const asset = ASSETS[path] || ASSETS[path.replace(/^\//, "/")];
    if (!asset) {
      return new Response("Not found", { status: 404 });
    }
    return new Response(asset.body, {
      headers: {
        "content-type": asset.contentType,
        "cache-control": path === "/sw.js" ? "no-cache" : "public, max-age=300"
      }
    });
  }
};
